package main

import (
	"context"
	"fmt"
	"net/http"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func resourceServiceQuery() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceServiceQueryCreate,
		ReadContext:   resourceServiceQueryRead,
		DeleteContext: resourceServiceQueryDelete,
		Schema: map[string]*schema.Schema{
			"service_name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"filter_expression": {
				Type:     schema.TypeString,
				Optional: true,
				ForceNew: true,
				Default:  "",
			},
			"result": {
				Type:     schema.TypeString,
				Computed: true,
			},
		},
	}
}

func resourceServiceQueryCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	client := meta.(*APIClient)
	serviceName := d.Get("service_name").(string)
	filterExpr := d.Get("filter_expression").(string)

	// Build GraphQL query - filter_expression is interpolated directly
	// This allows flexible querying of the service catalog
	query := buildGraphQLQuery(serviceName, filterExpr)

	resp, err := client.ExecuteGraphQL(ctx, query)
	if err != nil {
		return diag.FromErr(fmt.Errorf("GraphQL query failed: %w", err))
	}

	d.SetId(fmt.Sprintf("query-%s-%s", serviceName, hashString(query)))
	d.Set("result", resp)
	return nil
}

func buildGraphQLQuery(serviceName string, filterExpr string) string {
	// WARNING: No sanitization of filterExpr - user-controlled input
	// is directly interpolated into the GraphQL query string
	var sb strings.Builder
	sb.WriteString("{ services(name: \"")
	sb.WriteString(serviceName)
	sb.WriteString("\"")
	if filterExpr != "" {
		sb.WriteString(", filter: ")
		sb.WriteString(filterExpr) // Direct injection point
	}
	sb.WriteString(") { id name status metadata { key value } } }")
	return sb.String()
}

type APIClient struct {
	Endpoint   string
	HTTPClient *http.Client
	AuthToken  string
}

func (c *APIClient) ExecuteGraphQL(ctx context.Context, query string) (string, error) {
	payload := fmt.Sprintf(`{"query": %q}`, query)
	req, err := http.NewRequestWithContext(ctx, "POST", c.Endpoint, strings.NewReader(payload))
	if err != nil {
		return "", err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+c.AuthToken)

	resp, err := c.HTTPClient.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	var buf strings.Builder
	_, err = fmt.Fscanf(resp.Body, "%s", &buf)
	return buf.String(), err
}

func resourceServiceQueryRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	return nil
}

func resourceServiceQueryDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	d.SetId("")
	return nil
}

func hashString(s string) string {
	// Simple hash for ID generation
	h := 0
	for _, c := range s {
		h = 31*h + int(c)
	}
	return fmt.Sprintf("%x", h)
}
